55	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const isKnownItemType = (type: string): boolean =>
68	  type in BASE_PREMIUM_BY_ITEM_TYPE;
69	
70	const rejectUnknownItemTypes = (items: readonly Item[]): void => {
71	  const unknownItem = items.find((item) => !isKnownItemType(item.type));
72	
73	  if (unknownItem !== undefined) {
74	    throw new Error(`Unknown item type: ${unknownItem.type}`);
75	  }
76	};
77	
78	const itemBasePremiumOf = (item: Item): number =>
79	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
80	
81	const BLOCK_PREMIUM = 60;
82	const BLOCK_SIZE = 3;
83	
84	const itemsGroupedByType = (
85	  items: readonly Item[],
86	): readonly (readonly Item[])[] => [
87	  ...items
88	    .reduce(
89	      (groups, item) =>
90	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
91	      new Map<string, readonly Item[]>(),
92	    )
93	    .values(),
94	];
95	
96	const groupBasePremiumOf = (group: readonly Item[]): number =>
97	  group.length === BLOCK_SIZE
98	    ? BLOCK_PREMIUM
99	    : sumOf(group, itemBasePremiumOf);
100	
101	const CURSED_SURCHARGE_RATE = 0.5;
102	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
103	const HIGH_ENCHANTMENT_THRESHOLD = 5;
104	
105	const cursedSurchargeOf = (item: Item): number =>
106	  item.cursed === true ? itemBasePremiumOf(item) * CURSED_SURCHARGE_RATE : 0;
107	
108	const isHighlyEnchanted = (item: Item): boolean =>
109	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
110	
111	const highEnchantmentSurchargeOf = (item: Item): number =>
112	  isHighlyEnchanted(item)
113	    ? itemBasePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
114	    : 0;
115	
116	const itemSurchargeOf = (item: Item): number =>
117	  cursedSurchargeOf(item) + highEnchantmentSurchargeOf(item);
118	
119	const policyBasePremiumOf = (items: readonly Item[]): number =>
120	  sumOf(itemsGroupedByType(items), groupBasePremiumOf);
121	
122	const policySurchargeOf = (items: readonly Item[]): number =>
123	  sumOf(items, itemSurchargeOf);
124	
125	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
126	
127	const firstInsuranceSurchargeOf = (basePremium: number): number =>
128	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
129	
130	const LOYALTY_DISCOUNT_RATE = 0.2;
131	const LOYALTY_YEARS_THRESHOLD = 2;
132	
133	const loyaltyDiscountOf = (basePremium: number, customer: Customer): number =>
134	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
135	    ? basePremium * LOYALTY_DISCOUNT_RATE
136	    : 0;
137	
138	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
139	
140	const followUpDiscountOf = (
141	  basePremium: number,
142	  previousQuoteCount: number,
143	): number =>
144	  previousQuoteCount > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
145	
146	const exactPremiumBeforeFeeOf = (
147	  items: readonly Item[],
148	  customer: Customer,
149	  previousQuoteCount: number,
150	): number => {
151	  const basePremium = policyBasePremiumOf(items);
152	
153	  return (
154	    basePremium +
155	    policySurchargeOf(items) +
156	    firstInsuranceSurchargeOf(basePremium) -
157	    loyaltyDiscountOf(basePremium, customer) -
158	    followUpDiscountOf(basePremium, previousQuoteCount)
159	  );
160	};
161	
162	const PROCESSING_FEE = 5;
163	
164	const quotePremiumOf = (
165	  items: readonly Item[],
166	  customer: Customer,
167	  previousQuoteCount: number,
168	): number => {
169	  rejectUnknownItemTypes(items);
170	
171	  return Math.ceil(
172	    exactPremiumBeforeFeeOf(items, customer, previousQuoteCount) +
173	      PROCESSING_FEE,
174	  );
175	};
176	
177	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
178	  sword: 1000,
179	  rune: 250,
180	};
181	
182	const DEDUCTIBLE = 100;
183	const CAP_FACTOR = 2;
184	
185	const insuranceSumOf = (items: readonly Item[]): number =>
186	  sumOf(items, (item) => INSURANCE_VALUE_BY_ITEM_TYPE[item.type]);
187	
188	const payoutOf = (damage: Damage): number => damage.amount - DEDUCTIBLE;
189	
190	const capOf = (policy: QuoteStep): number =>
191	  insuranceSumOf(policy.items) * CAP_FACTOR;
192	
193	const claimResultOf = (
194	  step: ClaimStep,
195	  policies: readonly QuoteStep[],
196	): ClaimResult => {
197	  const payout = payoutOf(step.incident.damages[0]);
198	
199	  return { payout, remainingCap: capOf(policies[step.policy]) - payout };
200	};
201	
202	const quoteResultOf = (
203	  step: QuoteStep,
204	  customer: Customer,
205	  previousQuoteSteps: readonly QuoteStep[],
206	): QuoteResult => ({
207	  premium: quotePremiumOf(step.items, customer, previousQuoteSteps.length),
208	});
209	
210	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
211	
212	const quoteStepsOf = (steps: readonly Step[]): readonly QuoteStep[] =>
213	  steps.filter(isQuoteStep);
214	
215	const quoteStepsBefore = (
216	  steps: readonly Step[],
217	  stepIndex: number,
218	): readonly QuoteStep[] => quoteStepsOf(steps.slice(0, stepIndex));
219	
220	export const runScenario = (scenario: Scenario): ScenarioResult => ({
221	  results: scenario.steps.map((step, stepIndex): StepResult =>
222	    isQuoteStep(step)
223	      ? quoteResultOf(
224	          step,
225	          scenario.customer,
226	          quoteStepsBefore(scenario.steps, stepIndex),
227	        )
228	      : claimResultOf(step, quoteStepsOf(scenario.steps)),
229	  ),
230	});
